const overlay = document.getElementById('map-modal-overlay');
const modalPanel = overlay.querySelector('.map-modal-panel');
const closeBtn = document.getElementById('map-modal-close');
const svg = document.getElementById('india-map');
const SVG_NS = 'http://www.w3.org/2000/svg';
function renderStates() {
  const fragment = document.createDocumentFragment();
  const paintOrderedStates = MAP_STATES.filter(function (state) {
    return state.id !== 'Puducherry';
  });
  const puducherry = MAP_STATES.find(function (state) {
    return state.id === 'Puducherry';
  });

  if (puducherry) paintOrderedStates.push(puducherry);

  paintOrderedStates.forEach(function (state) {
    const group = document.createElementNS(SVG_NS, 'g');
    group.setAttribute('class', 'state');
    group.setAttribute('data-id', state.id);
    group.setAttribute('tabindex', '0');
    group.setAttribute('role', 'button');
    group.setAttribute('aria-label', state.display + ', state ' + state.code);
    group.style.transformOrigin = state.x + 'px ' + state.y + 'px';

    const path = document.createElementNS(SVG_NS, 'path');
    path.setAttribute('class', 'state-path');
    path.setAttribute('d', state.path);

    const code = document.createElementNS(SVG_NS, 'text');
    code.setAttribute('class', 'label-code');
    code.setAttribute('x', state.x);
    code.setAttribute('y', state.y);
    code.setAttribute('dy', '-3');
    code.setAttribute('text-anchor', 'middle');
    code.textContent = state.code;

    const name = document.createElementNS(SVG_NS, 'text');
    name.setAttribute('class', 'label-name');
    name.setAttribute('x', state.x);
    name.setAttribute('y', state.y);
    name.setAttribute('dy', '10');
    name.setAttribute('text-anchor', 'middle');
    name.textContent = state.display.toUpperCase();

    group.append(path, code, name);
    fragment.appendChild(group);
  });

  svg.appendChild(fragment);
}

renderStates();

const stateViews = new Map();
const stateSlots = new Map();
const restoreTimers = new WeakMap();
const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

let activeState = null;
let lastTrigger = null;

function promoteState(g) {
  if (g && g.parentNode === svg && svg.lastElementChild !== g) {
    svg.appendChild(g);
  }
}

function restoreState(g) {
  if (!g || g.classList.contains('is-hovered') ||
      g.classList.contains('is-focused') ||
      g.classList.contains('is-active')) return;

  const slot = stateSlots.get(g.dataset.id);
  if (slot && slot.parentNode === svg) {
    svg.insertBefore(g, slot.nextSibling);
  }
}

function cancelScheduledRestore(g) {
  const timer = restoreTimers.get(g);
  if (timer) {
    clearTimeout(timer);
    restoreTimers.delete(g);
  }
}

function scheduleRestore(g) {
  cancelScheduledRestore(g);
  const delay = reducedMotion.matches ? 0 : 480;
  const timer = setTimeout(function () {
    restoreTimers.delete(g);
    restoreState(g);
  }, delay);
  restoreTimers.set(g, timer);
}

function addStateFlag(g, className) {
  if (!g || g.classList.contains(className)) return;
  const wasElevated = g.classList.contains('is-hovered') ||
    g.classList.contains('is-focused') ||
    g.classList.contains('is-active');

  cancelScheduledRestore(g);
  promoteState(g);

  // Reordering an SVG group can otherwise collapse its transition into a
  // single frame. Flush the base pose before applying the elevated class.
  if (!wasElevated && !reducedMotion.matches) g.getBoundingClientRect();
  g.classList.add(className);
}

function removeStateFlag(g, className) {
  if (!g || !g.classList.contains(className)) return;
  g.classList.remove(className);
  scheduleRestore(g);
}

function setStateFlag(g, className, enabled) {
  if (enabled) addStateFlag(g, className);
  else removeStateFlag(g, className);
}

function setActive(g) {
  const previous = activeState;
  activeState = g;

  if (previous && previous !== g) {
    removeStateFlag(previous, 'is-active');
  }

  if (activeState) {
    addStateFlag(activeState, 'is-active');
  } else if (previous) {
    removeStateFlag(previous, 'is-active');
  }
}

function openModal(id, trigger) {
  const d = STATE_DATA[id];
  if (!d) return;

  lastTrigger = trigger;
  document.getElementById('map-modal-title').textContent = d.display;

  const centerRows = STATE_CENTER_DATA[id] || [{ city: d.capital, count: 0 }];
  const tableBody = document.getElementById('map-modal-center-rows');
  let totalCount = 0;
  tableBody.textContent = '';

  centerRows.forEach(function (center) {
    const count = Number(String(center.count).replace(/,/g, '')) || 0;
    const row = document.createElement('tr');
    const cityCell = document.createElement('td');
    const countCell = document.createElement('td');

    cityCell.textContent = center.city;
    countCell.textContent = count.toLocaleString('en-IN');
    row.appendChild(cityCell);
    row.appendChild(countCell);
    tableBody.appendChild(row);
    totalCount += count;
  });

  document.getElementById('map-modal-total').textContent = totalCount.toLocaleString('en-IN');
  overlay.classList.add('is-open');
  overlay.setAttribute('aria-hidden', 'false');
  document.body.classList.add('map-modal-open');
  requestAnimationFrame(function () { closeBtn.focus(); });
}

function closeModal() {
  const wasOpen = overlay.classList.contains('is-open');
  const trigger = lastTrigger;

  overlay.classList.remove('is-open');
  overlay.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('map-modal-open');
  setActive(null);
  lastTrigger = null;

  if (wasOpen && trigger && trigger.isConnected) {
    requestAnimationFrame(function () { trigger.focus(); });
  }
}

function activateState(hitTarget) {
  const id = hitTarget.dataset.id;
  const g = stateViews.get(id);
  if (!g || !STATE_DATA[id]) return;

  setActive(g);
  removeStateFlag(g, 'is-hovered');
  openModal(id, hitTarget);
}

// Visible state groups are free to move. Their cloned paths stay fixed and own
// all pointer/focus events, so elevation can never move the hit target away.
const hitLayer = document.createElementNS(SVG_NS, 'g');
hitLayer.setAttribute('class', 'state-hit-layer');
const calloutLayer = document.createElementNS(SVG_NS, 'g');
calloutLayer.setAttribute('class', 'state-callout-layer');
calloutLayer.setAttribute('aria-hidden', 'true');
calloutLayer.style.pointerEvents = 'none';
const hitEntries = [];

const defs = document.createElementNS(SVG_NS, 'defs');
defs.innerHTML = `
  <linearGradient id="state-top-gradient" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#edf6ff"></stop>
    <stop offset="58%" stop-color="#d5eaff"></stop>
    <stop offset="100%" stop-color="#bddcff"></stop>
  </linearGradient>
  <linearGradient id="state-hover-gradient" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#ffffff"></stop>
    <stop offset="52%" stop-color="#e6f4ff"></stop>
    <stop offset="100%" stop-color="#c7e7ff"></stop>
  </linearGradient>`;
svg.insertBefore(defs, svg.firstChild);

const LABEL_LINES = {
  AndhraPradesh: ['Andhra', 'Pradesh'],
  ArunachalPradesh: ['Arunachal', 'Pradesh'],
  HimachalPradesh: ['Himachal', 'Pradesh'],
  JammuandKashmir: ['Jammu &', 'Kashmir'],
  MadhyaPradesh: ['Madhya', 'Pradesh'],
  TamilNadu: ['Tamil', 'Nadu'],
  UttarPradesh: ['Uttar', 'Pradesh'],
  Uttaranchal: ['Uttarakhand'],
  WestBengal: ['West', 'Bengal']
};

const LABEL_ROTATIONS = {
  Chhattisgarh: -62,
  Kerala: -72
};

const CALLOUTS = {
  AndamanandNicobar: { x: 731, y: 793, anchor: 'start', lines: ['Andaman &', 'Nicobar Islands'] },
  Chandigarh: { x: 183, y: 229, anchor: 'end', lines: ['Chandigarh'] },
  DadraandNagarHaveli: { x: 59, y: 552, anchor: 'end', lines: ['Dadra &', 'Nagar Haveli'] },
  DamanandDiu: { x: 35, y: 502, anchor: 'end', lines: ['Daman & Diu'] },
  Delhi: { x: 267, y: 281, anchor: 'start', lines: ['Delhi'] },
  Goa: { x: 119, y: 672, anchor: 'end', lines: ['Goa'] },
  Lakshadweep: { x: 61, y: 867, anchor: 'end', lines: ['Lakshadweep'] },
  Manipur: { x: 755, y: 399, anchor: 'start', lines: ['Manipur'] },
  Mizoram: { x: 741, y: 446, anchor: 'start', lines: ['Mizoram'] },
  Nagaland: { x: 758, y: 351, anchor: 'start', lines: ['Nagaland'] },
  Puducherry: { x: 354, y: 786, targetX: 317, targetY: 758, anchor: 'start', lines: ['Puducherry'] },
  Sikkim: { x: 568, y: 279, anchor: 'start', lines: ['Sikkim'] },
  Tripura: { x: 607, y: 452, anchor: 'end', lines: ['Tripura'] }
};

function writeTextLines(textNode, lines, x, y, lineHeight) {
  textNode.textContent = '';
  textNode.setAttribute('x', x);
  textNode.setAttribute('y', y);
  textNode.removeAttribute('dy');
  lines.forEach(function (line, index) {
    const tspan = document.createElementNS(SVG_NS, 'tspan');
    tspan.setAttribute('x', x);
    tspan.setAttribute('dy', index === 0 ? -((lines.length - 1) * lineHeight) / 2 : lineHeight);
    tspan.textContent = line;
    textNode.appendChild(tspan);
  });
}

function addDepthLayers(g, sourcePath) {
  const depthGroup = document.createElementNS(SVG_NS, 'g');
  depthGroup.setAttribute('class', 'state-depth');
  depthGroup.setAttribute('aria-hidden', 'true');

  [12, 10, 8, 6, 4, 2].forEach(function (offset) {
    const slice = sourcePath.cloneNode(false);
    slice.removeAttribute('style');
    slice.removeAttribute('id');
    const depthClass = offset >= 9 ? 'depth-deep' : offset >= 5 ? 'depth-mid' : 'depth-shallow';
    slice.setAttribute('class', 'depth-slice ' + depthClass);
    slice.setAttribute('transform', 'translate(0 ' + offset + ')');
    depthGroup.appendChild(slice);
  });

  g.insertBefore(depthGroup, sourcePath);
}

function styleStateLabel(g, id) {
  const label = g.querySelector('.label-name');
  const code = g.querySelector('.label-code');
  if (!label) return;

  if (code) code.setAttribute('aria-hidden', 'true');
  const x = Number(label.getAttribute('x'));
  const y = Number(label.getAttribute('y'));
  const data = STATE_DATA[id];
  const lines = LABEL_LINES[id] || [data ? data.display : label.textContent];

  if (CALLOUTS[id]) {
    const config = CALLOUTS[id];
    label.classList.add('has-callout');

    const callout = document.createElementNS(SVG_NS, 'g');
    callout.setAttribute('class', 'state-callout');
    callout.setAttribute('aria-hidden', 'true');

    const targetX = config.targetX == null ? x : config.targetX;
    const targetY = config.targetY == null ? y : config.targetY;
    const lineEndX = config.anchor === 'end' ? config.x + 4 : config.x - 4;
    const elbowX = targetX + (lineEndX - targetX) * 0.54;
    const leader = document.createElementNS(SVG_NS, 'polyline');
    leader.setAttribute('points', targetX + ',' + targetY + ' ' + elbowX + ',' + targetY + ' ' + lineEndX + ',' + config.y);

    const marker = document.createElementNS(SVG_NS, 'circle');
    marker.setAttribute('cx', targetX);
    marker.setAttribute('cy', targetY);
    marker.setAttribute('r', '1.8');

    const text = document.createElementNS(SVG_NS, 'text');
    text.setAttribute('text-anchor', config.anchor);
    writeTextLines(text, config.lines, config.x, config.y, 12);

    callout.appendChild(leader);
    callout.appendChild(marker);
    callout.appendChild(text);
    calloutLayer.appendChild(callout);
    return;
  }

  writeTextLines(label, lines, x, y + 3, 13);
  if (LABEL_ROTATIONS[id]) {
    label.setAttribute('transform', 'rotate(' + LABEL_ROTATIONS[id] + ' ' + x + ' ' + y + ')');
  }
}

document.querySelectorAll('.state').forEach(function (g) {
  const id = g.dataset.id;
  const sourcePath = g.querySelector('.state-path');
  if (!id || !sourcePath) return;

  const slot = document.createComment('state-slot:' + id);
  svg.insertBefore(slot, g);
  stateSlots.set(id, slot);
  stateViews.set(id, g);

  sourcePath.removeAttribute('style');
  addDepthLayers(g, sourcePath);
  styleStateLabel(g, id);

  const hit = sourcePath.cloneNode(false);
  hit.removeAttribute('style');
  hit.removeAttribute('id');
  hit.setAttribute('class', 'state-hit');
  hit.setAttribute('data-id', id);
  hit.setAttribute('tabindex', '0');
  hit.setAttribute('role', 'button');
  hit.setAttribute('aria-label', g.getAttribute('aria-label') || id);

  g.removeAttribute('tabindex');
  g.removeAttribute('role');
  g.removeAttribute('aria-label');
  g.setAttribute('aria-hidden', 'true');

  hit.addEventListener('pointerenter', function (e) {
    if (e.pointerType !== 'touch') setStateFlag(g, 'is-hovered', true);
  });
  hit.addEventListener('pointerleave', function (e) {
    if (e.pointerType !== 'touch') setStateFlag(g, 'is-hovered', false);
  });
  hit.addEventListener('focus', function () {
    setStateFlag(g, 'is-focused', true);
  });
  hit.addEventListener('blur', function () {
    setStateFlag(g, 'is-focused', false);
  });
  hit.addEventListener('click', function () {
    activateState(hit);
  });
  hit.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      activateState(hit);
    }
  });

  const bounds = sourcePath.getBBox();
  hitEntries.push({
    hit: hit,
    area: id === 'Puducherry' ? -1 : bounds.width * bounds.height
  });
});

// Paint large territories first and small/enclosed territories last so places
// such as Delhi remain reachable instead of being covered by a neighbour.
hitEntries.sort(function (a, b) { return b.area - a.area; });
hitEntries.forEach(function (entry) { hitLayer.appendChild(entry.hit); });
svg.appendChild(calloutLayer);
svg.appendChild(hitLayer);

closeBtn.addEventListener('click', closeModal);
overlay.addEventListener('click', function (e) {
  if (e.target === overlay) closeModal();
});
document.addEventListener('keydown', function (e) {
  if (!overlay.classList.contains('is-open')) return;

  if (e.key === 'Escape') {
    e.preventDefault();
    closeModal();
    return;
  }

  if (e.key === 'Tab') {
    const focusable = Array.from(modalPanel.querySelectorAll(
      'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
    ));

    if (!focusable.length) {
      e.preventDefault();
      modalPanel.focus();
      return;
    }

    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }
});
